CREATE TABLE IF NOT EXISTS "members" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login and delivery-notification identity.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name printed on the shipping label.
	"full_name" VARCHAR(160) NOT NULL,
	-- Current delivery address. Cycles snapshot their own copy, so a member moving house does not rewrite where last quarter box went.
	"shipping_address" JSONB NOT NULL,
	-- IANA zone. Cutoff reminders and skip deadlines are only fair if they land in local time.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Personal share code. Generated at signup for everyone, because asking members to opt in to referring loses most of the channel.
	"referral_code" VARCHAR(20) NOT NULL UNIQUE,
	-- active | dormant | deleted. Dormant is a member with no live subscription who still has credit and history.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "members" IS 'The person. Kept separate from subscriptions because a member can hold two boxes at once and can cancel one and keep the other.';
COMMENT ON COLUMN "members"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "members"."email" IS 'Login and delivery-notification identity.';
COMMENT ON COLUMN "members"."full_name" IS 'Name printed on the shipping label.';
COMMENT ON COLUMN "members"."shipping_address" IS 'Current delivery address. Cycles snapshot their own copy, so a member moving house does not rewrite where last quarter box went.';
COMMENT ON COLUMN "members"."timezone" IS 'IANA zone. Cutoff reminders and skip deadlines are only fair if they land in local time.';
COMMENT ON COLUMN "members"."referral_code" IS 'Personal share code. Generated at signup for everyone, because asking members to opt in to referring loses most of the channel.';
COMMENT ON COLUMN "members"."status" IS 'active | dormant | deleted. Dormant is a member with no live subscription who still has credit and history.';
COMMENT ON COLUMN "members"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "plans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine name such as classic_monthly. Referenced by curation rules so the marketing name can change freely.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Customer-facing plan name.
	"name" VARCHAR(120) NOT NULL,
	-- month | week. Combined with interval_count to derive the next cycle date.
	"interval_unit" VARCHAR(10) NOT NULL DEFAULT 'month',
	-- Number of units between boxes. Two here with month gives the common every-other-month box.
	"interval_count" INTEGER NOT NULL DEFAULT 1,
	-- Recurring price in minor units. Integers only - never float money.
	"price_minor" INTEGER NOT NULL,
	-- ISO 4217 currency for price_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Target item count. The curation engine reads it as a target, not a guarantee, which is why it is not a constraint.
	"items_per_box" INTEGER NOT NULL DEFAULT 5,
	-- Days before the ship date after which a member can no longer skip or change preferences. Set per plan because a fresh-food box has a much tighter window than a book box.
	"cutoff_days_before" INTEGER NOT NULL DEFAULT 5,
	-- Retired plans stay for existing members but leave the signup page.
	"active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "plans" IS 'The commercial product. Cadence lives here rather than on the subscription so a plan-wide change to shipping rhythm is one row.';
COMMENT ON COLUMN "plans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "plans"."code" IS 'Stable machine name such as classic_monthly. Referenced by curation rules so the marketing name can change freely.';
COMMENT ON COLUMN "plans"."name" IS 'Customer-facing plan name.';
COMMENT ON COLUMN "plans"."interval_unit" IS 'month | week. Combined with interval_count to derive the next cycle date.';
COMMENT ON COLUMN "plans"."interval_count" IS 'Number of units between boxes. Two here with month gives the common every-other-month box.';
COMMENT ON COLUMN "plans"."price_minor" IS 'Recurring price in minor units. Integers only - never float money.';
COMMENT ON COLUMN "plans"."currency_code" IS 'ISO 4217 currency for price_minor.';
COMMENT ON COLUMN "plans"."items_per_box" IS 'Target item count. The curation engine reads it as a target, not a guarantee, which is why it is not a constraint.';
COMMENT ON COLUMN "plans"."cutoff_days_before" IS 'Days before the ship date after which a member can no longer skip or change preferences. Set per plan because a fresh-food box has a much tighter window than a book box.';
COMMENT ON COLUMN "plans"."active" IS 'Retired plans stay for existing members but leave the signup page.';

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner.
	"member_id" BIGINT NOT NULL,
	-- Plan currently subscribed to. Plan changes update this and take effect from the next unbilled cycle.
	"plan_id" BIGINT NOT NULL,
	-- active | paused | past_due | cancelled. Paused is distinct from cancelled because a paused member still has a resume date and still counts as retained.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- Local date the next cycle will be generated. The single column the nightly job scans, which is why it is indexed on its own.
	"next_cycle_date" DATE NOT NULL,
	-- Resume date while paused. Null when active; a pause with no end date is just a slow cancellation.
	"paused_until" DATE,
	-- Gateway payment method token. Null right after signup through a channel that collects payment later.
	"payment_method_reference" VARCHAR(120),
	-- First activation. Kept across plan changes so tenure and cohort analysis survive an upgrade.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When cancellation took effect. Set alongside the cancellations row.
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscriptions" IS 'The recurring commitment. It holds only the forward-looking state; everything that has already happened lives in billing_cycles, which is what keeps this row small and hot.';
COMMENT ON COLUMN "subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscriptions"."member_id" IS 'Owner.';
COMMENT ON COLUMN "subscriptions"."plan_id" IS 'Plan currently subscribed to. Plan changes update this and take effect from the next unbilled cycle.';
COMMENT ON COLUMN "subscriptions"."status" IS 'active | paused | past_due | cancelled. Paused is distinct from cancelled because a paused member still has a resume date and still counts as retained.';
COMMENT ON COLUMN "subscriptions"."next_cycle_date" IS 'Local date the next cycle will be generated. The single column the nightly job scans, which is why it is indexed on its own.';
COMMENT ON COLUMN "subscriptions"."paused_until" IS 'Resume date while paused. Null when active; a pause with no end date is just a slow cancellation.';
COMMENT ON COLUMN "subscriptions"."payment_method_reference" IS 'Gateway payment method token. Null right after signup through a channel that collects payment later.';
COMMENT ON COLUMN "subscriptions"."started_at" IS 'First activation. Kept across plan changes so tenure and cohort analysis survive an upgrade.';
COMMENT ON COLUMN "subscriptions"."cancelled_at" IS 'When cancellation took effect. Set alongside the cancellations row.';

CREATE INDEX "idx_subscriptions_due"
ON "subscriptions" ("status", "next_cycle_date");
CREATE INDEX "idx_subscriptions_member_status"
ON "subscriptions" ("member_id", "status");

CREATE TABLE IF NOT EXISTS "billing_cycles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent subscription.
	"subscription_id" BIGINT NOT NULL,
	-- Monotonic per subscription starting at 1. What support and the member both call the third box.
	"cycle_number" INTEGER NOT NULL,
	-- First day of the period this box covers.
	"period_start" DATE NOT NULL,
	-- Last day of the period, inclusive.
	"period_end" DATE NOT NULL,
	-- Planned dispatch date. Fixed when the cycle is created so warehouse capacity can be planned weeks ahead.
	"ship_date" DATE NOT NULL,
	-- Last date a member may skip, derived from the plan cutoff and frozen here so a later plan edit cannot retroactively close a window a member was told was open.
	"skip_deadline" DATE NOT NULL,
	-- scheduled | skipped | billed | payment_failed | curated | shipped | delivered | refunded. The whole lifecycle of one box.
	"status" VARCHAR(20) NOT NULL DEFAULT 'scheduled',
	-- Amount to charge, snapshotted from the plan and adjusted by credit. A price rise must not reprice cycles already scheduled.
	"amount_minor" INTEGER NOT NULL,
	-- Referral or goodwill credit consumed by this cycle, recorded here as well as in the ledger so an invoice reconciles without a join.
	"credit_applied_minor" INTEGER NOT NULL DEFAULT 0,
	-- Currency of the amounts.
	"currency_code" CHAR(3) NOT NULL,
	-- Gateway charge id. Unique so a replayed webhook cannot bill a cycle twice.
	"charge_reference" VARCHAR(120) UNIQUE,
	-- When the charge succeeded. Null while scheduled or skipped.
	"billed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "billing_cycles" IS 'One row per box, created ahead of time in scheduled state. Every operation a subscription business performs - bill, skip, curate, pick, ship, refund - is a state change on this row.';
COMMENT ON COLUMN "billing_cycles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "billing_cycles"."subscription_id" IS 'Parent subscription.';
COMMENT ON COLUMN "billing_cycles"."cycle_number" IS 'Monotonic per subscription starting at 1. What support and the member both call the third box.';
COMMENT ON COLUMN "billing_cycles"."period_start" IS 'First day of the period this box covers.';
COMMENT ON COLUMN "billing_cycles"."period_end" IS 'Last day of the period, inclusive.';
COMMENT ON COLUMN "billing_cycles"."ship_date" IS 'Planned dispatch date. Fixed when the cycle is created so warehouse capacity can be planned weeks ahead.';
COMMENT ON COLUMN "billing_cycles"."skip_deadline" IS 'Last date a member may skip, derived from the plan cutoff and frozen here so a later plan edit cannot retroactively close a window a member was told was open.';
COMMENT ON COLUMN "billing_cycles"."status" IS 'scheduled | skipped | billed | payment_failed | curated | shipped | delivered | refunded. The whole lifecycle of one box.';
COMMENT ON COLUMN "billing_cycles"."amount_minor" IS 'Amount to charge, snapshotted from the plan and adjusted by credit. A price rise must not reprice cycles already scheduled.';
COMMENT ON COLUMN "billing_cycles"."credit_applied_minor" IS 'Referral or goodwill credit consumed by this cycle, recorded here as well as in the ledger so an invoice reconciles without a join.';
COMMENT ON COLUMN "billing_cycles"."currency_code" IS 'Currency of the amounts.';
COMMENT ON COLUMN "billing_cycles"."charge_reference" IS 'Gateway charge id. Unique so a replayed webhook cannot bill a cycle twice.';
COMMENT ON COLUMN "billing_cycles"."billed_at" IS 'When the charge succeeded. Null while scheduled or skipped.';

CREATE UNIQUE INDEX "uq_cycles_subscription_number"
ON "billing_cycles" ("subscription_id", "cycle_number");
CREATE INDEX "idx_cycles_status_ship_date"
ON "billing_cycles" ("status", "ship_date");

CREATE TABLE IF NOT EXISTS "member_preferences" (
	-- Subscription the preference applies to. Per subscription rather than per member, because a household can hold a coffee box and a tea box with opposite answers.
	"subscription_id" BIGINT,
	-- Preference key such as roast_level, size or avoid_allergen. Composite with subscription_id, so setting a preference is a single upsert.
	"attribute" VARCHAR(60),
	-- Chosen value. Kept as text because the vocabulary changes every season and a column per attribute means a migration per season.
	"value" VARCHAR(120) NOT NULL,
	-- True for allergies and sizing, which the curation engine must never violate. Soft preferences are only ranked. Collapsing the two is how somebody gets sent nuts.
	"is_hard_constraint" BOOLEAN NOT NULL DEFAULT false,
	-- Last change. Changes after a cycle skip_deadline apply from the following box.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("subscription_id", "attribute")
);

COMMENT ON TABLE "member_preferences" IS 'The curation inputs, as an entity-attribute table. Hard constraints and soft preferences are deliberately one table with a flag, so the engine reads one query and cannot forget an allergy.';
COMMENT ON COLUMN "member_preferences"."subscription_id" IS 'Subscription the preference applies to. Per subscription rather than per member, because a household can hold a coffee box and a tea box with opposite answers.';
COMMENT ON COLUMN "member_preferences"."attribute" IS 'Preference key such as roast_level, size or avoid_allergen. Composite with subscription_id, so setting a preference is a single upsert.';
COMMENT ON COLUMN "member_preferences"."value" IS 'Chosen value. Kept as text because the vocabulary changes every season and a column per attribute means a migration per season.';
COMMENT ON COLUMN "member_preferences"."is_hard_constraint" IS 'True for allergies and sizing, which the curation engine must never violate. Soft preferences are only ranked. Collapsing the two is how somebody gets sent nuts.';
COMMENT ON COLUMN "member_preferences"."updated_at" IS 'Last change. Changes after a cycle skip_deadline apply from the following box.';

CREATE TABLE IF NOT EXISTS "products" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stock keeping unit the warehouse picks by.
	"sku" VARCHAR(64) NOT NULL UNIQUE,
	-- Product name printed in the box insert card.
	"name" VARCHAR(200) NOT NULL,
	-- Supplier brand. Null for own-label items.
	"brand" VARCHAR(160),
	-- Curation facets such as {"roast":"dark","contains":["milk"]}. Matched against member preferences, including the allergen checks.
	"attributes" JSONB NOT NULL DEFAULT '''{}''',
	-- What the box costs to source, in minor units. The basis for per-box margin, which is the number that decides whether a plan survives.
	"unit_cost_minor" INTEGER NOT NULL,
	-- Units available to allocate. Curation reserves against this, which is what stops a season planning more boxes than there is stock.
	"on_hand" INTEGER NOT NULL DEFAULT 0,
	-- Earliest date the item may appear in a box. Null when always available.
	"available_from" DATE,
	-- Last date it may appear. Seasonal items expire rather than being deleted, so old box contents still resolve.
	"available_until" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "products" IS 'The pool curation picks from. Products are never hard-deleted because a box shipped two years ago must still be able to name what was in it.';
COMMENT ON COLUMN "products"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "products"."sku" IS 'Stock keeping unit the warehouse picks by.';
COMMENT ON COLUMN "products"."name" IS 'Product name printed in the box insert card.';
COMMENT ON COLUMN "products"."brand" IS 'Supplier brand. Null for own-label items.';
COMMENT ON COLUMN "products"."attributes" IS 'Curation facets such as {"roast":"dark","contains":["milk"]}. Matched against member preferences, including the allergen checks.';
COMMENT ON COLUMN "products"."unit_cost_minor" IS 'What the box costs to source, in minor units. The basis for per-box margin, which is the number that decides whether a plan survives.';
COMMENT ON COLUMN "products"."on_hand" IS 'Units available to allocate. Curation reserves against this, which is what stops a season planning more boxes than there is stock.';
COMMENT ON COLUMN "products"."available_from" IS 'Earliest date the item may appear in a box. Null when always available.';
COMMENT ON COLUMN "products"."available_until" IS 'Last date it may appear. Seasonal items expire rather than being deleted, so old box contents still resolve.';

CREATE INDEX "idx_products_availability"
ON "products" ("available_from", "available_until");

CREATE TABLE IF NOT EXISTS "cycle_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Box this item goes in.
	"billing_cycle_id" BIGINT NOT NULL,
	-- Product allocated. Nullable only so a product row removed in error does not destroy box history.
	"product_id" BIGINT,
	-- SKU snapshot, the pick list value that still works if the product row changes.
	"sku" VARCHAR(64) NOT NULL,
	-- Name snapshot, printed on the insert card that ships in the box.
	"name" VARCHAR(200) NOT NULL,
	-- Units of this product in the box.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	-- Cost snapshot at curation time, so per-box margin is computable years later without re-reading supplier prices.
	"unit_cost_minor" INTEGER NOT NULL,
	-- Why curation chose it, e.g. matched_roast_preference or new_member_staple. What makes a bad box explainable instead of mysterious.
	"selection_reason" VARCHAR(60),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cycle_items" IS 'The contents of one box. Personalised boxes mean no two rows for the same cycle_number look alike, which is exactly why contents hang off the cycle and not off the plan.';
COMMENT ON COLUMN "cycle_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cycle_items"."billing_cycle_id" IS 'Box this item goes in.';
COMMENT ON COLUMN "cycle_items"."product_id" IS 'Product allocated. Nullable only so a product row removed in error does not destroy box history.';
COMMENT ON COLUMN "cycle_items"."sku" IS 'SKU snapshot, the pick list value that still works if the product row changes.';
COMMENT ON COLUMN "cycle_items"."name" IS 'Name snapshot, printed on the insert card that ships in the box.';
COMMENT ON COLUMN "cycle_items"."quantity" IS 'Units of this product in the box.';
COMMENT ON COLUMN "cycle_items"."unit_cost_minor" IS 'Cost snapshot at curation time, so per-box margin is computable years later without re-reading supplier prices.';
COMMENT ON COLUMN "cycle_items"."selection_reason" IS 'Why curation chose it, e.g. matched_roast_preference or new_member_staple. What makes a bad box explainable instead of mysterious.';

CREATE INDEX "idx_cycle_items_cycle"
ON "cycle_items" ("billing_cycle_id");
CREATE INDEX "idx_cycle_items_product"
ON "cycle_items" ("product_id");

CREATE TABLE IF NOT EXISTS "shipments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Box being shipped.
	"billing_cycle_id" BIGINT NOT NULL,
	-- Carrier name.
	"carrier" VARCHAR(60) NOT NULL,
	-- Tracking number once a label is bought.
	"tracking_number" VARCHAR(80),
	-- Address copied from the member at label time. A member moving mid-cycle must not change where the box already went.
	"address_snapshot" JSONB NOT NULL,
	-- pending | in_transit | delivered | returned | lost. Returned and lost are separated because only one of them is the carrier fault.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Handover to the carrier.
	"shipped_at" TIMESTAMPTZ,
	-- Confirmed delivery. The trigger for the review and the unboxing email.
	"delivered_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shipments" IS 'A parcel per cycle. It is its own table rather than columns on the cycle because a lost box is reshipped, and the second parcel needs its own tracking and its own outcome.';
COMMENT ON COLUMN "shipments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shipments"."billing_cycle_id" IS 'Box being shipped.';
COMMENT ON COLUMN "shipments"."carrier" IS 'Carrier name.';
COMMENT ON COLUMN "shipments"."tracking_number" IS 'Tracking number once a label is bought.';
COMMENT ON COLUMN "shipments"."address_snapshot" IS 'Address copied from the member at label time. A member moving mid-cycle must not change where the box already went.';
COMMENT ON COLUMN "shipments"."status" IS 'pending | in_transit | delivered | returned | lost. Returned and lost are separated because only one of them is the carrier fault.';
COMMENT ON COLUMN "shipments"."shipped_at" IS 'Handover to the carrier.';
COMMENT ON COLUMN "shipments"."delivered_at" IS 'Confirmed delivery. The trigger for the review and the unboxing email.';

CREATE INDEX "idx_shipments_cycle"
ON "shipments" ("billing_cycle_id");
CREATE INDEX "idx_shipments_status_shipped"
ON "shipments" ("status", "shipped_at");

CREATE TABLE IF NOT EXISTS "subscription_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscription the event happened to.
	"subscription_id" BIGINT NOT NULL,
	-- skip | pause | resume | plan_change | address_change | reactivate | cancel. The full lifecycle vocabulary.
	"event_type" VARCHAR(30) NOT NULL,
	-- Cycle affected. Set for a skip, null for a pause, which is exactly how the two are told apart later.
	"billing_cycle_id" BIGINT,
	-- Local date the change takes effect, which is often not the date it was requested.
	"effective_date" DATE NOT NULL,
	-- Event-specific payload such as the old and new plan codes.
	"detail" JSONB,
	-- member | support | system. A system pause after three failed payments must not be counted as voluntary churn.
	"created_by" VARCHAR(20) NOT NULL DEFAULT 'member',
	-- When the event was recorded.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscription_events" IS 'An append-only lifecycle log. Skips and pauses are events rather than columns because a member who skipped four boxes and one who paused for four months are wildly different retention stories.';
COMMENT ON COLUMN "subscription_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscription_events"."subscription_id" IS 'Subscription the event happened to.';
COMMENT ON COLUMN "subscription_events"."event_type" IS 'skip | pause | resume | plan_change | address_change | reactivate | cancel. The full lifecycle vocabulary.';
COMMENT ON COLUMN "subscription_events"."billing_cycle_id" IS 'Cycle affected. Set for a skip, null for a pause, which is exactly how the two are told apart later.';
COMMENT ON COLUMN "subscription_events"."effective_date" IS 'Local date the change takes effect, which is often not the date it was requested.';
COMMENT ON COLUMN "subscription_events"."detail" IS 'Event-specific payload such as the old and new plan codes.';
COMMENT ON COLUMN "subscription_events"."created_by" IS 'member | support | system. A system pause after three failed payments must not be counted as voluntary churn.';
COMMENT ON COLUMN "subscription_events"."created_at" IS 'When the event was recorded.';

CREATE INDEX "idx_events_subscription_created"
ON "subscription_events" ("subscription_id", "created_at");
CREATE INDEX "idx_events_type_effective"
ON "subscription_events" ("event_type", "effective_date");

CREATE TABLE IF NOT EXISTS "cancellation_reasons" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine name such as too_expensive. Stable ids are what let a reason be reworded without breaking two years of cohort charts.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Wording shown in the cancellation flow.
	"label" VARCHAR(160) NOT NULL,
	-- price | product_fit | too_much_product | life_change | service. The grouping the retention team actually reports on.
	"category" VARCHAR(30) NOT NULL,
	-- Whether a win-back offer is worth making. Nobody should be offered a discount for moving abroad.
	"is_recoverable" BOOLEAN NOT NULL DEFAULT true,
	-- Order in the cancellation form. Order changes response distribution, so it is data rather than markup.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cancellation_reasons" IS 'A lookup, not free text. Churn reasons are only useful if they are comparable across quarters, which means a fixed id behind a rewritable label.';
COMMENT ON COLUMN "cancellation_reasons"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cancellation_reasons"."code" IS 'Stable machine name such as too_expensive. Stable ids are what let a reason be reworded without breaking two years of cohort charts.';
COMMENT ON COLUMN "cancellation_reasons"."label" IS 'Wording shown in the cancellation flow.';
COMMENT ON COLUMN "cancellation_reasons"."category" IS 'price | product_fit | too_much_product | life_change | service. The grouping the retention team actually reports on.';
COMMENT ON COLUMN "cancellation_reasons"."is_recoverable" IS 'Whether a win-back offer is worth making. Nobody should be offered a discount for moving abroad.';
COMMENT ON COLUMN "cancellation_reasons"."position" IS 'Order in the cancellation form. Order changes response distribution, so it is data rather than markup.';

CREATE TABLE IF NOT EXISTS "cancellations" (
	-- Subscription cancelled. Primary key, so a subscription cancels exactly once; a reactivated member starts a new subscription row.
	"subscription_id" BIGINT,
	-- Selected reason.
	"reason_id" BIGINT NOT NULL,
	-- Free-text elaboration. Optional, and the single most read field in the whole retention review.
	"comment" VARCHAR(600),
	-- Final cycle actually shipped. Null when a member cancels before any box goes out, which is a different failure mode entirely.
	"last_cycle_id" BIGINT,
	-- Offer presented during the flow. Null when none was, which is what makes offer effectiveness measurable.
	"winback_offer_code" VARCHAR(40),
	-- Whether the save attempt worked.
	"winback_accepted" BOOLEAN NOT NULL DEFAULT false,
	-- When the cancellation was confirmed.
	"cancelled_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("subscription_id")
);

COMMENT ON TABLE "cancellations" IS 'The exit interview, one row per subscription. Keeping it out of subscriptions stops seven mostly-null columns sitting on the hottest table in the schema.';
COMMENT ON COLUMN "cancellations"."subscription_id" IS 'Subscription cancelled. Primary key, so a subscription cancels exactly once; a reactivated member starts a new subscription row.';
COMMENT ON COLUMN "cancellations"."reason_id" IS 'Selected reason.';
COMMENT ON COLUMN "cancellations"."comment" IS 'Free-text elaboration. Optional, and the single most read field in the whole retention review.';
COMMENT ON COLUMN "cancellations"."last_cycle_id" IS 'Final cycle actually shipped. Null when a member cancels before any box goes out, which is a different failure mode entirely.';
COMMENT ON COLUMN "cancellations"."winback_offer_code" IS 'Offer presented during the flow. Null when none was, which is what makes offer effectiveness measurable.';
COMMENT ON COLUMN "cancellations"."winback_accepted" IS 'Whether the save attempt worked.';
COMMENT ON COLUMN "cancellations"."cancelled_at" IS 'When the cancellation was confirmed.';

CREATE INDEX "idx_cancellations_reason_date"
ON "cancellations" ("reason_id", "cancelled_at");

CREATE TABLE IF NOT EXISTS "referrals" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Member who shared the code.
	"referrer_id" BIGINT NOT NULL,
	-- Member who signed up. Unique so one person cannot be claimed by two referrers, and null while the invite is outstanding.
	"referred_member_id" BIGINT UNIQUE,
	-- Code as typed, snapshotted in case the referrer later rotates it.
	"code_used" VARCHAR(20) NOT NULL,
	-- pending | qualified | rewarded | void. Qualified means the referred member paid for a first box, which is the only moment a reward is safe to grant.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- When the first successful charge landed for the referred member.
	"qualified_at" TIMESTAMPTZ,
	-- When the invite was used.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "referrals" IS 'The referral relationship, held separately from the credit it produces. Rewards are only granted at qualified, because paying on signup is a standing invitation to fraud.';
COMMENT ON COLUMN "referrals"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "referrals"."referrer_id" IS 'Member who shared the code.';
COMMENT ON COLUMN "referrals"."referred_member_id" IS 'Member who signed up. Unique so one person cannot be claimed by two referrers, and null while the invite is outstanding.';
COMMENT ON COLUMN "referrals"."code_used" IS 'Code as typed, snapshotted in case the referrer later rotates it.';
COMMENT ON COLUMN "referrals"."status" IS 'pending | qualified | rewarded | void. Qualified means the referred member paid for a first box, which is the only moment a reward is safe to grant.';
COMMENT ON COLUMN "referrals"."qualified_at" IS 'When the first successful charge landed for the referred member.';
COMMENT ON COLUMN "referrals"."created_at" IS 'When the invite was used.';

CREATE INDEX "idx_referrals_referrer_status"
ON "referrals" ("referrer_id", "status");

CREATE TABLE IF NOT EXISTS "credits" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Member whose balance this affects.
	"member_id" BIGINT NOT NULL,
	-- referral | goodwill | refund | promotion | redemption. Redemption rows are the negative side of the ledger.
	"source" VARCHAR(24) NOT NULL,
	-- Referral that generated the credit. Null for goodwill and refunds.
	"referral_id" BIGINT,
	-- Cycle a redemption was applied to. Null on a grant, set on a redemption, which is how the two halves pair up.
	"applied_to_cycle_id" BIGINT,
	-- Signed amount in minor units. Positive for a grant, negative for a redemption, so the balance is one SUM.
	"amount_minor" INTEGER NOT NULL,
	-- Currency. Credit is never converted; a balance in one currency cannot pay a cycle in another.
	"currency_code" CHAR(3) NOT NULL,
	-- Expiry date. Null for credit that never expires, such as a refund the member is owed.
	"expires_at" DATE,
	-- When the entry was written.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "credits" IS 'An append-only credit ledger. A balance column on members would be overwritten by two concurrent redemptions and would leave nothing to explain where the money came from.';
COMMENT ON COLUMN "credits"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "credits"."member_id" IS 'Member whose balance this affects.';
COMMENT ON COLUMN "credits"."source" IS 'referral | goodwill | refund | promotion | redemption. Redemption rows are the negative side of the ledger.';
COMMENT ON COLUMN "credits"."referral_id" IS 'Referral that generated the credit. Null for goodwill and refunds.';
COMMENT ON COLUMN "credits"."applied_to_cycle_id" IS 'Cycle a redemption was applied to. Null on a grant, set on a redemption, which is how the two halves pair up.';
COMMENT ON COLUMN "credits"."amount_minor" IS 'Signed amount in minor units. Positive for a grant, negative for a redemption, so the balance is one SUM.';
COMMENT ON COLUMN "credits"."currency_code" IS 'Currency. Credit is never converted; a balance in one currency cannot pay a cycle in another.';
COMMENT ON COLUMN "credits"."expires_at" IS 'Expiry date. Null for credit that never expires, such as a refund the member is owed.';
COMMENT ON COLUMN "credits"."created_at" IS 'When the entry was written.';

CREATE INDEX "idx_credits_member_created"
ON "credits" ("member_id", "created_at");
CREATE INDEX "idx_credits_cycle"
ON "credits" ("applied_to_cycle_id");

